import { createHash } from 'node:crypto';

export const generatedHeader =
  '/* @generated by tools/polyfill-bundle — do not edit by hand; run `pnpm build` */\n';

/// 只替换已生成文件的独立 banner，拒绝未知格式，保持依赖 bundle 原样。
export function replaceBanner(artifact, source) {
  const normalizedHeader = artifact.slice(0, artifact.indexOf('\n') + 1)
    .replace(/\r\n/g, '\n');
  if (normalizedHeader !== generatedHeader) {
    throw new Error('产物缺少预期的生成标记，请执行完整构建');
  }
  const boundary = /\r?\n\r?\n(?=\(\(\)=>\{)/.exec(artifact);
  if (!boundary) {
    throw new Error('无法定位 banner 与 IIFE 的边界，请执行完整构建');
  }
  const bundle = artifact.slice(boundary.index + boundary[0].length);
  return {
    artifact: generatedHeader + source.trimEnd() + '\n\n' + bundle,
    bundleHash: createHash('sha256').update(bundle).digest('hex'),
  };
}
